import assert from 'node:assert/strict'
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { createManualClock, systemClock } from '../src/main/clock'
import { createMemoryEngine } from '../src/main/memory/engine'
import { createMemoryDatabaseClient } from '../src/main/memory/storage/client'
import { createNativeMemoryDatabase } from '../src/main/memory/storage/neo'
import { createApiMemoryEmbeddingSource } from '../src/main/memory/airi/embedding'

async function run() {
const original = 'D:/.lca-cache/continuity10-tests/retrieval-live-20261104-1/zh'
const root = 'D:/.lca-cache/continuity10-tests/embedding-deadline-diagnostic-20261104-2'
const files = ['memory.duckdb', 'runtime.json', 'operations.log']
const hash = (path: string) => createHash('sha256').update(readFileSync(path)).digest('hex')
const before = Object.fromEntries(files.map(file => [file, hash(original + '/' + file)]))
mkdirSync(root)
const results: Record<string, unknown>[] = []
for (const bodyDelayMs of [2500, 3500]) {
  const directory = root + '/' + bodyDelayMs; mkdirSync(directory)
  for (const file of files) copyFileSync(original + '/' + file, directory + '/' + file)
  const clock = createManualClock(1793635200000)
  const events: { kind: string; atMs: number }[] = []
  let started!: () => void, settled!: () => void
  const fetchStarted = new Promise<void>(resolve => { started = resolve })
  const embedSettled = new Promise<void>(resolve => { settled = resolve })
  let requests = 0, begin = clock.nowMs()
  const raw = createApiMemoryEmbeddingSource({ baseUrl: 'https://api.voyageai.com/v1', apiKey: 'synthetic-only', model: 'voyage-4-large', clock,
    fetch: async (_url, init) => {
      requests++; begin = clock.nowMs(); events.push({ kind: 'request', atMs: 0 }); started()
      assert.equal(JSON.parse(String(init?.body)).input_type, 'query', 'UNEXPECTED_MIGRATION')
      const body = new ReadableStream<Uint8Array>({ start(controller) {
        clock.after(bodyDelayMs, () => { events.push({ kind: 'body-complete', atMs: clock.nowMs() - begin }); controller.enqueue(Buffer.from(JSON.stringify({ data: [{ embedding: Array.from({ length: 1024 }, (_, index) => index === 0 ? 1 : 0) }] }))); controller.close() })
      } })
      return new Promise<Response>(resolve => clock.after(362, () => { events.push({ kind: 'headers-200', atMs: clock.nowMs() - begin }); resolve(new Response(body)) }))
    } })
  const source = { ...raw, embed: async (text: string, kind?: 'query' | 'document') => { try { return await raw.embed(text, kind) } finally { events.push({ kind: 'embed-settled', atMs: clock.nowMs() - begin }); settled() } } }
  const engine = createMemoryEngine({ root: directory, owner: { userId: 'retrieval-fixture-zh', characterId: 'taozi', dataRootId: 'quality-zh' }, clock,
    embedding: () => source, held: () => false, waitForRestore: async () => {}, journal: () => {},
    openDatabase: async path => { const db = createMemoryDatabaseClient(createNativeMemoryDatabase(), systemClock); await db.open(path); return db } })
  try {
    assert.ok(await engine.runtime.initialize())
    await engine.runtime.refreshEmbedding(); assert.equal(requests, 0)
    const pending = engine.runtime.retrieveEvaluationTrace('留学', 'offline-deadline', { userId: 'retrieval-fixture-zh', characterId: 'taozi' })
    await fetchStarted; clock.advanceBy(362); await new Promise<void>(resolve => setImmediate(resolve))
    clock.advanceBy(Math.min(bodyDelayMs, 3000) - 362)
    const trace = await pending
    const returnedAtMs = clock.nowMs() - begin
    const error = engine.runtime.embeddingError.value
    if (bodyDelayMs > 3000) { assert.match(error ?? '', /Memory embedding exceeded 3000 ms/); assert.deepEqual(trace.retrievedIds, []); clock.advanceBy(bodyDelayMs - 3000) }
    else assert.equal(error, undefined)
    await embedSettled
    assert.equal(requests, 1); assert.equal(engine.runtime.databaseStatus.value, 'ready')
    results.push({ bodyDelayMs, returnedAtMs, error: error ?? null, databaseState: engine.runtime.databaseStatus.value, requests, networkRequests: 0, lateVectorNotReturned: bodyDelayMs > 3000 ? trace.retrievedIds.length === 0 : null, events })
  } finally { await engine.dispose() }
}
const after = Object.fromEntries(files.map(file => [file, hash(original + '/' + file)]))
assert.deepEqual(after, before)
const report = { ok: true, syntheticOnly: true, originalUnchanged: true, originalHashes: before, copiedDataRoot: root, results,
  inference: 'The original live failure lacks its transient runtime error, so timing and this controlled reproduction support, but do not conclusively prove, the 3000 ms interaction deadline as its cause.' }
writeFileSync('test-results/continuity/candidate10-embedding-deadline-diagnostic-20261104.json', JSON.stringify(report, null, 2))
console.log(JSON.stringify(report))
}
void run().catch(error => { console.error(error); process.exitCode = 1 })

import { build } from 'vite'
import { spawn } from 'node:child_process'
import { resolve } from 'node:path'
await build({ configFile: false, logLevel: 'error', build: { ssr: '.cache/embedding-deadline-fixture.ts', outDir: '.cache/embedding-deadline-bundle', emptyOutDir: false,
  minify: false, rollupOptions: { external: ['@duckdb/node-api', 'better-sqlite3'], output: { format: 'cjs', entryFileNames: 'probe.cjs' } } } })
const child = spawn(process.execPath, [resolve('.cache/embedding-deadline-bundle/probe.cjs')], { windowsHide: true, stdio: 'inherit' })
const timeout = setTimeout(() => child.kill(), 60000)
const code = await new Promise((done, fail) => { child.once('error', fail); child.once('exit', done) }); clearTimeout(timeout)
process.exitCode = code ?? 1

import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { _electron } from 'playwright'
import { runtimeEnv } from '../scripts/runtime-env.mjs'

const original = 'D:/.lca-cache/continuity10-tests/retrieval-diagnostics-preflight-20261104-1'
const root = 'D:/.lca-cache/continuity10-tests/duckdb-electron-lifetime-20261104-1'
const repo = resolve(import.meta.dirname, '..')
const databases = ['zh', 'en'].map(language => join(original, language, 'memory.duckdb'))
const hash = async file => createHash('sha256').update(await readFile(file)).digest('hex')
const before = await Promise.all(databases.map(hash))
const { sql } = JSON.parse(await readFile(join(original, 'storage-failure.json'), 'utf8'))
const executablePath = 'C:/.lca-cache/continuity10-release-20261103/win-unpacked/LoveCollegeAgent.exe'
const report = { readOnly: true, original, originalHashes: before, asarSha256: await hash(join(dirname(executablePath), 'resources/app.asar')), queriesPerVariant: 80, results: [] }
await mkdir(root)
for (const explicitClose of [false, true]) {
  const profile = join(root, explicitClose ? 'close' : 'implicit')
  const env = { ...runtimeEnv(repo), LCA_DATA_DIR: profile, LCA_PROVIDERS_FILE: join(profile, 'absent.json'), LCA_TEST_SILENT: '1', LCA_MCP_PORT: '0', LCA_CDP_PORT: '0' }
  delete env.DSH_ROOT; delete env.LCA_BOOTH; delete env.ELECTRON_RENDERER_URL
  delete env.LCA_MEMORY_CONNECTION_FILE; delete env.LCA_CONTINUITY_AUTH_FILE
  const app = await _electron.launch({ executablePath, args: [], env, timeout: 30000 })
  const timer = setTimeout(() => { void app.close() }, 45000)
  try {
    report.results.push(await app.evaluate(async (_, input) => {
      const { DuckDBInstance } = process.mainModule.require(input.module)
      const instances = [], connections = []
      const result = { explicitClose: input.explicitClose, completed: 0, ok: false, samples: [], error: null, memoryLimits: [] }
      try {
        for (const path of input.databases) {
          const instance = await DuckDBInstance.create(path, { access_mode: 'READ_ONLY', threads: '2', autoinstall_known_extensions: 'false', autoload_known_extensions: 'false' })
          instances.push(instance); const connection = await instance.connect(); connections.push(connection)
          const settings = await connection.runAndReadAll("SELECT current_setting('memory_limit') AS memory_limit")
          result.memoryLimits.push(settings.getRowObjectsJS()[0]); settings.closeSync()
        }
        for (let index = 0; index < 80; index++) {
          const reader = await connections[index % 2].runAndReadAll(input.sql)
          try {
            const rows = reader.getRowObjectsJS()
            if (rows.length !== (index % 2 === 0 ? 20 : 10)) throw new Error('UNEXPECTED_CORPUS_COUNT:' + rows.length)
          } finally { if (input.explicitClose) reader.closeSync() }
          result.completed++
          const memory = await process.getProcessMemoryInfo()
          result.samples.push({ query: index + 1, rss: process.memoryUsage().rss, privateKiB: memory.private })
          if (process.memoryUsage().rss > 1280 * 1024 ** 2 || memory.private > 2 * 1024 ** 2) throw new Error('DIAGNOSTIC_RESOURCE_CAP')
        }
        result.ok = true
      } catch (error) { result.error = error.message }
      finally { for (const connection of connections) connection.closeSync(); for (const instance of instances) instance.closeSync() }
      return result
    }, { module: join(repo, 'node_modules/@duckdb/node-api'), databases, sql, explicitClose }))
  } catch (error) { report.results.push({ explicitClose, ok: false, runnerError: error.message }) }
  finally { clearTimeout(timer); await app.close() }
}
assert.deepEqual(await Promise.all(databases.map(hash)), before)
report.originalUnchanged = true
await writeFile('test-results/continuity/candidate10-duckdb-electron-lifetime-20261104.json', JSON.stringify(report, null, 2), { flag: 'wx' })
console.log(JSON.stringify({ originalUnchanged: true, results: report.results.map(({ samples, ...result }) => ({ ...result, sampledPeakRssBytes: samples?.length ? Math.max(...samples.map(value => value.rss)) : null, sampledPeakPrivateKiB: samples?.length ? Math.max(...samples.map(value => value.privateKiB)) : null })) }))
